CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "agent_wakeup_requests_task_operation_uq" ON "agent_wakeup_requests" USING btree ("company_id","idempotency_key") WHERE "agent_wakeup_requests"."idempotency_key" LIKE 'task-operation:%' OR "agent_wakeup_requests"."idempotency_key" LIKE 'task-operation-dispatch:%';